import concurrent.futures as cf

def with_timeout(fn, *args, seconds=5):
    # run the tool body under a hard wall-clock cap
    with cf.ThreadPoolExecutor(max_workers=1) as ex:
        fut = ex.submit(fn, *args)
        try:
            return fut.result(timeout=seconds)
        except cf.TimeoutError:
            raise TimeoutError(f"tool exceeded {seconds}s budget")

MAX_CHARS = 10_000
def cap_output(text: str) -> str:
    return text[:MAX_CHARS]   # never flood the model's context

def run_tool(raw_args: dict) -> dict:
    try:
        args = RunReportArgs(**raw_args)      # validate
    except ValidationError as e:
        # structured, model-actionable, NO internals leaked
        return {"ok": False, "error": "invalid_arguments",
                "detail": "metric must be revenue|signups; days 1-90"}
    result = _run(args)
    return {"ok": True, "result": result}
# the model sees a clear reason and can retry with fixed arguments.

