from pathlib import Path

SANDBOX = Path("/srv/agent-files").resolve()

# UNSAFE: opens whatever the model sends.
def read_file_unsafe(path: str) -> str:
    return open(path).read()   # '../../etc/passwd' escapes freely

# SAFE: resolve against the sandbox, then verify containment.
def read_file_safe(rel_path: str) -> str:
    candidate = (SANDBOX / rel_path).resolve()
    if not candidate.is_relative_to(SANDBOX):
        raise PermissionError("path escapes the allowed directory")
    return candidate.read_text()

# demonstrate the containment check without touching the real FS:
for attempt in ["notes.txt", "../../etc/passwd"]:
    resolved = (SANDBOX / attempt).resolve()
    inside = resolved.is_relative_to(SANDBOX)
    print(f"{attempt!r:22} -> inside sandbox: {inside}")

import time
import concurrent.futures as cf
from pydantic import BaseModel, Field, ValidationError

class Args(BaseModel):
    model_config = {"extra": "forbid"}           # reject hallucinated keys
    metric: str = Field(pattern="^(revenue|signups)$")  # allow-list
    days: int = Field(ge=1, le=90)               # bounded

MAX_CHARS = 50

def _work(args: Args, delay: float) -> str:
    time.sleep(delay)                            # simulate work
    return f"{args.metric} for {args.days} days" * 5

def handle(raw: dict, delay: float = 0.0, timeout: float = 1.0) -> dict:
    try:
        args = Args(**raw)                       # 1) validate untrusted input
    except ValidationError:
        return {"ok": False, "error": "invalid_arguments",
                "detail": "metric must be revenue|signups; days 1-90"}
    try:
        with cf.ThreadPoolExecutor(max_workers=1) as ex:  # 2) bound time
            text = ex.submit(_work, args, delay).result(timeout=timeout)
    except cf.TimeoutError:
        return {"ok": False, "error": "timeout", "detail": "tool too slow"}
    return {"ok": True, "result": text[:MAX_CHARS]}  # 3) cap output size

print(handle({"metric": "revenue", "days": 7}))
print(handle({"metric": "drop_table", "days": 7}))
print(handle({"metric": "revenue", "days": 7}, delay=2.0, timeout=0.2))

