from pathlib import Path

def safe_read(rel_path: str, sandbox: str) -> dict:
    # 1) validate the untrusted argument
    if not isinstance(rel_path, str) or not rel_path.strip():
        return {"ok": False, "error": "invalid_arguments"}

    root = Path(sandbox).resolve()
    # 2) resolve against the sandbox and check containment
    candidate = (root / rel_path).resolve()
    if not candidate.is_relative_to(root):
        return {"ok": False, "error": "forbidden"}

    # 3) success -- return the resolved path (no open() here)
    return {"ok": True, "path": str(candidate)}

