from pydantic import BaseModel, Field, ValidationError

class ReportArgs(BaseModel):
    model_config = {"extra": "forbid"}                 # reject extra keys
    metric: str = Field(pattern="^(revenue|signups)$")  # allow-list
    days: int = Field(ge=1, le=90)                     # bounded range

def validate_args(raw: dict) -> dict:
    try:
        args = ReportArgs(**raw)
    except ValidationError:
        # structured + model-actionable; no internals leaked
        return {"ok": False, "error": "invalid_arguments",
                "detail": "metric must be revenue|signups; days must be 1-90"}
    return {"ok": True, "args": {"metric": args.metric, "days": args.days}}

if __name__ == "__main__":
    print(validate_args({"metric": "revenue", "days": 7}))
    print(validate_args({"metric": "revenue", "days": 999}))
    print(validate_args({"metric": "revenue", "days": 7, "evil": "x"}))
